local KTool = CS.Engine.Lib.KTool
local ActivityPtUtils = import('Game.UI.FightReady.UIActivityPt.ActivityPtUtils')
local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
local UIModule = CS.Engine.UI.UIModule
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数
------------ import ------------
       
local TaskType = {
    Day = 1,
    Plan = 2,
}
--- from: Assets/BundleResources/Prefabs/ActivityPt/12000108/ActivityPtTaskDialog.prefab > name: ActivityPtTaskDialog
---@class UIActivityPtTaskNode     
---@field Env                           	UIActivityPtTaskNode                    
