local UIActivityPtTaskNode = Class('UIActivityPtTaskNode')

function UIActivityPtTaskNode:__init()
    self._labels = {}
    self._dayTask = {}
    self._planTask = {}
    self._curLabelInd = 1
    self._curTasks = {}
    self._curTaskType = 1
end

function UIActivityPtTaskNode:__delete()
    self._dayTask = nil
    self._planTask = nil
    self._labels = nil
    self._curLabelInd = 1
    self._curTasks = {}
    self._curTaskType = 1
end

function UIActivityPtTaskNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyRewards))
end

function UIActivityPtTaskNode:OneKeyRewards()
    if isNull(self._curTaskType)  then
        return
    end
    local isDraw = false
    for k, v in pairs(self._curTasks) do
        if checkInt(v.status) == 1 then
            isDraw = true
            break
        end
    end
    if not isDraw then
        GameUtils.Toast(localize("暂无奖励可以领取"))
        return
    end
    ActivityPtComponent:OverseaActivityPtQuestDrawTaskReq(self._curUuid, 0, self._curTaskType, function()
        self:InitTaskData()
        self:FillLabel()
        self:FillTaskList()
    end)
end

function UIActivityPtTaskNode:Refresh(activityUuid)
    self._curUuid = checkNumber(activityUuid)

    self:InitData()
    self:FillSelf()

    self:StartTimeDown()
end

function UIActivityPtTaskNode:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
        local time = ActivityPtComponent:GetDailyTaskTimeLeft()
        if time < 0 then
            ActivityPtComponent:OverseaActivityPtQuestTaskReq(self._curUuid, function()
                self:InitData()
                self:FillSelf()
            end)
        end
    end, CountDownTime, false, true)
end

function UIActivityPtTaskNode:InitData()
    self._labels = {
        {
            type = TaskType.Day,
            name = localize("日常任务"),
        },
        {
            type = TaskType.Plan,
            name = localize("限定任务"),
        }
    }
    self._curLabelInd = 1
end

function UIActivityPtTaskNode:FillSelf()
    self:FillLabel()

    self:InitTaskData()
    self:FillTaskList(TaskType.Day)
    self:FillTime()
end

function UIActivityPtTaskNode:FillTime()
    local time = 0
    if self._curTaskType == TaskType.Day then
        time = ActivityPtComponent:GetDailyTaskTimeLeft()
    else
        time = ActivityPtComponent:GetPlanTaskTimeLeft()
    end

    CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
end

function UIActivityPtTaskNode:FillLabel()
    if not self.LeftTabItem.IsListViewInit then
        self.LeftTabItem:InitListView(#self._labels, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LeftTabItem, #self._labels)
    end
end

function UIActivityPtTaskNode:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local go = cell.gameObject
    local data = self._labels[index + 1]

    local isSelect = (checkNumber(self._curLabelInd) == (index + 1))
    CfUtils.PlayAnimation(go, isSelect and "ActivityPtTaskDialog_select" or "ActivityPtTaskDialog_default")
    local transform = go.transform
    local ImgBg = go.transform:Find("ImgBg")
    local ImgIcon = go.transform:Find("ImgIcon")
    local ImgBgSelect = go.transform:Find("ImgBgSelect")
    local ImgIconSelect = go.transform:Find("ImgIconSelect")
    local redPoint = go.transform:Find("redPoint")
    local TxtName = go.transform:Find("TxtName")
    CfUtils.SetActive(ImgBg, not isSelect)
    CfUtils.SetActive(ImgIcon, not isSelect)
    CfUtils.SetActive(ImgBgSelect, isSelect)
    CfUtils.SetActive(ImgIconSelect, isSelect)
    CfUtils.SetActive(redPoint, ActivityPtUtils.IsTypeHasCanDrawReward(data.type))
    CfUtils.SetUISwitchImage(ImgIcon, (index + 1) == 1 and 1 or 2)
    CfUtils.SetUISwitchImage(ImgBgSelect, (data.type == TaskType.Day) and 1 or 2)
    CfUtils.SetUISwitchImage(ImgIconSelect, (data.type == TaskType.Day) and 1 or 2)
    CfUtils.FillText(TxtName, data.name)
    CfUtils.SetUISwitchText(TxtName, isSelect and 2 or 1)

    local num1, num2 = 0, 0
    if data.type == TaskType.Day then
        num1, num2 = ActivityPtUtils.GetFinishDayTask()
    else
        num1, num2 = ActivityPtUtils.GetFinishPlanTask()
    end 
    CfUtils.FillText(go.transform:Find("TxtNum"), num1.."/"..num2)

    SetButtonAction(go, Bind(self, self.OnBtnSelectPlot, index + 1))

    return cell
end

function UIActivityPtTaskNode:OnBtnSelectPlot(ind)
    if ind == self._curLabelInd then
        return
    end
    local curInd = checkNumber(self._curLabelInd)
    if curInd then
        local go = self.LeftTabItem:GetShownItemByItemIndex(curInd - 1)
        if go then
            CfUtils.PlayAnimation(go, "ActivityPtTaskDialog_default")
            CfUtils.SetUISwitchText(go.transform:Find("TxtName"), 1)
        end 
    end
    self._curLabelInd = checkNumber(ind)
    self._curTaskType = self._labels[self._curLabelInd].type

    curInd = checkNumber(self._curLabelInd)
    if curInd then
        local go = self.LeftTabItem:GetShownItemByItemIndex(curInd - 1)
        if go then
            CfUtils.PlayAnimation(go, "ActivityPtTaskDialog_select")
            CfUtils.SetUISwitchText(go.transform:Find("TxtName"), 2)
        end 
    end
    self:InitTaskData()
    self:FillTaskList()
    self:FillTime()
end 

function UIActivityPtTaskNode:InitTaskData()
    local t = {}
    self._curTasks = {}
    if self._curTaskType == TaskType.Day then
        t = ActivityPtComponent:GetDailyTask()
        for k, v in pairs(t) do
            if checkNumber(v.status) == 2 then
                v.sortKey = 3
            elseif checkNumber(v.status) == 1 then
                v.sortKey = 1
            elseif checkNumber(v.status) == 0 then
                v.sortKey = 2
            end
            table.insert(self._curTasks, v)
        end
    else 
        t = ActivityPtComponent:GetPlanTask()
        for k, v in pairs(t) do
            if checkNumber(v.status) == 2 then
                v.sortKey = 3
            elseif checkNumber(v.status) == 1 then
                v.sortKey = 1
            elseif checkNumber(v.status) == 0 then
                v.sortKey = 2
            end
            table.insert(self._curTasks, v)
        end
    end
    table.sort(self._curTasks, function(a, b)
        if a.sortKey == b.sortKey then
            return checkNumber(a.id) < checkNumber(b.id)
        else 
            return checkNumber(a.sortKey) < checkNumber(b.sortKey)
        end        
    end)
end

function UIActivityPtTaskNode:FillTaskList()
    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(#self._curTasks, Bind(self, self.OnGetItemTaskByIndex))
    else
        GameUtils.ReloadData(self.ListView, #self._curTasks)
    end
end

function UIActivityPtTaskNode:OnGetItemTaskByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("CellNode")
    local go = cell.gameObject
    local data = self._curTasks[index + 1]
    CfUtils.PlayAnimation(go, "ActivityPtTaskDialog_CellNode_change")

    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIActivityPt.ActivityPtTaskDialog.UIActivityPtTaskCellNode")
    if scr then
        scr:Refresh(data, self._curTaskType, function()
            ActivityPtComponent:OverseaActivityPtQuestDrawTaskReq(self._curUuid, data.id, self._curTaskType, function()
                scr:FillSelf()
                self:FillLabel()
            end)
        end)
    end

    return cell
end

